1	// Acceptance test for the change request:
2	//   "Let me see just the open tasks on a project. Or just the finished ones."
3	//
4	// A project's task list (on its detail page, /projects/<id>) gains a control
5	// (data-testid="task-filter") that narrows the list to tasks at ONE stage. A task is either OPEN
6	// (not yet done) or DONE (ticked off — the request calls these the "finished" ones), so choosing a
7	// stage leaves only the tasks at that stage: choose OPEN and only the un-ticked tasks remain; choose
8	// DONE and only the ticked-off ones remain. Before a stage is chosen the list is unfiltered (every
9	// task on the project shows). Choosing the other stage narrows to THAT stage, and returning to "all
10	// tasks" brings every task back — so the filter is genuinely keyed on the chosen stage and not
11	// hardwired to one. Because a filter outlives a click (CLAUDE.md rule 4) the chosen stage lives in
12	// the URL and survives a fresh load. Filtering is a pure view concern: it records nothing.
13	//
14	// The contract for the control mirrors its sibling invoice-status-filter: it is a <select> on the
15	// project detail page with one option per stage (its label NAMING the stage — open / done i.e.
16	// finished) plus a default "all tasks" option carrying an empty value (no stage => unfiltered). The
17	// test chooses a stage by finding the option whose label NAMES that stage (case-insensitively) and
18	// selecting it by the option's own value, so it binds to the stage's MEANING, not the exact value or
19	// capitalisation the control uses internally — the same way the sibling specs match task-status by
20	// the stage word.
21	//
22	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
23	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
24	// honours { id, name, email }, `projects` honours { id, name, clientId } and `tasks` honours
25	// { id, title, projectId, done }.
26	import { test, expect, type Page, type Locator } from '@playwright/test';
27	import { resetAndSeed } from '../support/seed';
28	import { auditLines } from '../support/audit';
29	
30	// A task's status cell reads "done" once ticked off and some other way ("open"/…) while not — matched
31	// by the WORD, case-insensitively, so the test binds to the MEANING and not one capitalisation.
32	const DONE = /\bdone\b/i;
33	
34	// The two stages, matched by the WORD(s) that name them in the filter's option labels. "open" is the
35	// un-ticked stage; the finished stage may be labelled "done" or "finished" (the request's own word),
36	// so either names it. Word boundaries keep the stages distinct and keep the default "all tasks"
37	// option (which names neither) out of both.
38	const OPEN = /\bopen\b/i;
39	const FINISHED = /\b(?:done|finished|complete)/i;
40	
41	const taskRows = (page: Page) => page.locator('[data-testid^="task-row-"]');
42	const statusOf = (page: Page, id: number): Locator =>
43	  page.getByTestId(`task-row-${id}`).getByTestId('task-status');
44	
45	// A spread of open and finished tasks on one project, plus a task on a DIFFERENT project that must
46	// never appear here regardless of the filter. More than one task at each stage so narrowing to a
47	// stage must drop several rows — a filter that merely hid one row could not reproduce these results.
48	const SEED = {
49	  clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
50	  projects: [
51	    { id: 1, name: 'Website Redesign', clientId: 1 },
52	    { id: 2, name: 'Mobile App', clientId: 1 },
53	  ],
54	  tasks: [
55	    { id: 1, title: 'Draft the brief', projectId: 1, done: false },
56	    { id: 2, title: 'Build the homepage', projectId: 1, done: true },
57	    { id: 3, title: 'Review with client', projectId: 1, done: false },
58	    { id: 4, title: 'Launch announcement', projectId: 1, done: true },
59	    { id: 5, title: 'Gather feedback', projectId: 1, done: false },
60	    // A task on another project must not show here under ANY filter.
61	    { id: 6, title: 'Ship to the store', projectId: 2, done: false },
62	  ],
63	};
64	
65	const OPEN_IDS = [1, 3, 5];
66	const DONE_IDS = [2, 4];
67	const ALL_IDS = [1, 2, 3, 4, 5];
68	
69	// The ids of the currently-rendered task rows, ascending (order is not what this feature is about).
70	async function visibleIds(page: Page): Promise<number[]> {
71	  return taskRows(page).evaluateAll((els) =>
72	    els
73	      .map((el) => Number(el.getAttribute('data-testid')!.replace('task-row-', '')))
74	      .sort((a, b) => a - b),
75	  );
76	}
77	
78	// Choose a stage in the filter. The option is found by the stage WORD in its label and selected by
79	// that option's own value, so the stage is pinned by meaning, not by an exact value/capitalisation.
80	async function chooseStage(page: Page, word: RegExp): Promise<void> {
81	  const filter = page.getByTestId('task-filter');
82	  await expect(filter).toBeVisible();
83	  const value = await filter
84	    .locator('option')
85	    .filter({ hasText: word })
86	    .first()
87	    .evaluate((el: HTMLOptionElement) => el.value);
88	  await filter.selectOption(value);
89	}
90	
91	// Return the filter to "all tasks": the default option carries no stage, so it has an empty value
92	// (an empty value clears the URL key, leaving the list unfiltered) — same mechanism as the sibling
93	// invoice-status-filter.
94	async function chooseAllTasks(page: Page): Promise<void> {
95	  await page.getByTestId('task-filter').selectOption('');
96	}
97	
98	test.describe('See just the open tasks on a project, or just the finished ones', () => {
99	  test('the project page offers a task filter and lists every task before one is chosen', async ({
100	    page,
101	  }) => {
102	    await resetAndSeed(SEED);
103	
104	    await page.goto('/projects/1');
105	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
106	
107	    // The new filter control is present on the page.
108	    await expect(page.getByTestId('task-filter')).toBeVisible();
109	
110	    // Before any stage is chosen the list is unfiltered: every task on THIS project is shown, and
111	    // the other project's task is not.
112	    await expect(page.getByTestId('project-tasks-table')).toBeVisible();
113	    await expect(taskRows(page)).toHaveCount(ALL_IDS.length);
114	    expect(await visibleIds(page)).toEqual(ALL_IDS);
115	    await expect(page.getByTestId('task-row-6')).toHaveCount(0);
116	  });
117	
118	  test('choosing "open" narrows the list to only the open tasks', async ({ page }) => {
119	    await resetAndSeed(SEED);
120	
121	    await page.goto('/projects/1');
122	    // Precondition: everything is listed, so the narrowing below is a real effect of the filter.
123	    await expect(taskRows(page)).toHaveCount(ALL_IDS.length);
124	
125	    await chooseStage(page, OPEN);
126	
127	    // Only the open tasks remain; every finished task has dropped out of the list.
128	    await expect(taskRows(page)).toHaveCount(OPEN_IDS.length);
129	    expect(await visibleIds(page)).toEqual(OPEN_IDS);
130	    for (const id of OPEN_IDS) {
131	      await expect(page.getByTestId(`task-row-${id}`)).toBeVisible();
132	      await expect(statusOf(page, id)).not.toHaveText(DONE);
133	    }
134	    for (const id of DONE_IDS) {
135	      await expect(page.getByTestId(`task-row-${id}`)).toHaveCount(0);
136	    }
137	
138	    // The surviving rows still carry their real data — narrowing filters the list, it does not blank it.
139	    await expect(page.getByTestId('task-row-1').getByTestId('task-title')).toHaveText('Draft the brief');
140	    await expect(page.getByTestId('task-row-3').getByTestId('task-title')).toHaveText('Review with client');
141	  });
142	
143	  test('the filter is keyed on the chosen stage: each stage narrows to its own tasks', async ({
144	    page,
145	  }) => {
146	    await resetAndSeed(SEED);
147	
148	    await page.goto('/projects/1');
149	
150	    // Finished tasks only — the request's "just the finished ones".
151	    await chooseStage(page, FINISHED);
152	    await expect(taskRows(page)).toHaveCount(DONE_IDS.length);
153	    expect(await visibleIds(page)).toEqual(DONE_IDS);
154	    for (const id of DONE_IDS) {
155	      await expect(statusOf(page, id)).toHaveText(DONE);
156	    }
157	
158	    // Switching to open narrows to a DIFFERENT set — proof the filter follows the chosen stage and
159	    // is not hardwired to one (the finished tasks are gone, the open ones are now shown).
160	    await chooseStage(page, OPEN);
161	    await expect(taskRows(page)).toHaveCount(OPEN_IDS.length);
162	    expect(await visibleIds(page)).toEqual(OPEN_IDS);
163	    for (const id of OPEN_IDS) {
164	      await expect(statusOf(page, id)).not.toHaveText(DONE);
165	    }
166	
167	    // Returning to "all tasks" brings every task back.
168	    await chooseAllTasks(page);
169	    await expect(taskRows(page)).toHaveCount(ALL_IDS.length);
170	    expect(await visibleIds(page)).toEqual(ALL_IDS);
171	  });
172	
173	  test('the chosen stage survives a fresh load, and filtering records nothing', async ({ page }) => {
174	    await resetAndSeed(SEED);
175	
